oxy_webhelp_navlinks = {"sql_protect_mssql_databases-d39307e35690":{"topics":[{"title":"SLA Domain assignments for SQL Server objects","shortdesc":"<p class=\"shortdesc\">Assigning an SLA Domain activates automated protection for your Microsoft SQL Server         databases. Direct or inherited SLA Domain assignment supports policy-driven management of         database and log backups.<\/p>","href":"saas\/mssql_sla_domain_assignments.html","attributes":{"data-id":"mssql_sla_domain_assignments"},"menu":{"hasChildren":false},"tocID":"mssql_sla_domain_assignments-d39307e35703","topics":[]},{"title":"Changing the default log backup path","shortdesc":"<p class=\"shortdesc\">Edit the default log backup properties to change the log backup location for a         protected Microsoft SQL Server database.<\/p>","href":"saas\/mssql_setting_default_log_backup_frequency.html","attributes":{"data-id":"mssql_setting_default_log_backup_frequency"},"menu":{"hasChildren":false},"tocID":"mssql_setting_default_log_backup_frequency-d39307e35714","topics":[]},{"title":"Log backup retention","shortdesc":"<p class=\"shortdesc\">An SLA Domain controls whether to archive and replicate Microsoft SQL Server log         backups and enables different retention periods per target.<\/p>","href":"saas\/mssql_log_backup_retention.html","attributes":{"data-id":"mssql_log_backup_retention"},"menu":{"hasChildren":false},"tocID":"mssql_log_backup_retention-d39307e35725","topics":[]},{"title":"Protecting databases through a parent object","shortdesc":"<p class=\"shortdesc\">Assign an SLA Domain to a Windows Server host, Microsoft SQL Server instance, or         individual databases to protect Microsoft SQL Server databases. Derived assignments from a         host or instance allow uniform management and protection of database groups.<\/p>","href":"saas\/mssql_protecting_dbs_through_parent_obj.html","attributes":{"data-id":"mssql_protecting_dbs_through_parent_obj"},"menu":{"hasChildren":false},"tocID":"mssql_protecting_dbs_through_parent_obj-d39307e35736","topics":[]},{"title":"Protecting individual Microsoft SQL Server databases","shortdesc":"<p class=\"shortdesc\">To provide data management and protection for an individual Microsoft SQL Server database,         assign that database to an SLA Domain.<\/p>","href":"saas\/mssql_protecting_individual_dbs.html","attributes":{"data-id":"mssql_protecting_individual_dbs"},"menu":{"hasChildren":false},"tocID":"mssql_protecting_individual_dbs-d39307e35747","topics":[]},{"title":"Removing Microsoft SQL Server database protection ","shortdesc":"<p class=\"shortdesc\">Remove an SLA Domain assignment from a Microsoft SQL Server database to prevent         policy-driven snapshots and log backups for the database. Both derived and individual SLA         Domain assignments can be removed.<\/p>","href":"saas\/mssql_removing_sla_domain_assignment.html","attributes":{"data-id":"mssql_removing_sla_domain_assignment"},"menu":{"hasChildren":false},"tocID":"mssql_removing_sla_domain_assignment-d39307e35758","topics":[]},{"title":"Taking an on-demand snapshot ","shortdesc":"<p class=\"shortdesc\">Create an on-demand snapshot of the databases on a Microsoft SQL Server instance or         of individual Microsoft SQL Server database.<\/p>","href":"saas\/mssql_taking_on_demand_snapshot.html","attributes":{"data-id":"mssql_taking_on_demand_snapshot"},"menu":{"hasChildren":false},"tocID":"mssql_taking_on_demand_snapshot-d39307e35769","topics":[]},{"title":"Taking a group on-demand snapshot task","shortdesc":"<p class=\"shortdesc\">Take a single on-demand snapshot of a group of Microsoft SQL Server databases to use         fewer resources than are required to take an on-demand snapshot of each individual database         in the group.<\/p>","href":"saas\/mssql_taking_group_on_demand_snapshot_task.html","attributes":{"data-id":"mssql_taking_group_on_demand_snapshot_task"},"menu":{"hasChildren":false},"tocID":"mssql_taking_group_on_demand_snapshot_task-d39307e35780","topics":[]},{"title":"Creating an on-demand T-log backup","shortdesc":"<p class=\"shortdesc\">Create an on-demand T-log backup to protect records that were written to the         transaction log after the most recent transaction log backup.<\/p>","href":"saas\/mssql_creating_a_t_log_backup.html","attributes":{"data-id":"mssql_creating_a_t_log_backup"},"menu":{"hasChildren":false},"tocID":"mssql_creating_a_t_log_backup-d39307e35791","topics":[]},{"title":"Microsoft SQL Server backup immutability","shortdesc":"<p class=\"shortdesc\">When you archive Microsoft SQL Server backup data to an archival location with an         immutability policy, <span class=\"ph\">RSC<\/span> automatically protects SQL Server database snapshot         and log backup files with object-level locks that prevent deletion for the duration of the         retention period.<\/p>","href":"saas\/mssql_backup_immutability.html","attributes":{"data-id":"mssql_backup_immutability"},"menu":{"hasChildren":false},"tocID":"mssql_backup_immutability-d39307e35802","topics":[]},{"title":"Pausing and resuming protection for Microsoft SQL Server databases","shortdesc":"<p class=\"shortdesc\">Pause scheduled backup, archival, and replication actions for         a specific database workload without affecting the protection of other objects managed by         the SLA Domain.<\/p>","href":"saas\/mssql_pausing_resuming_protection.html","attributes":{"data-id":"mssql_pausing_resuming_protection"},"menu":{"hasChildren":false},"tocID":"mssql_pausing_resuming_protection-d39307e35817","topics":[]},{"title":"High Availability for Microsoft SQL Server workloads","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides High Availability Policies that you can assign to         Microsoft SQL Server workloads to maintain uninterrupted backup and recovery operations         against hardware failures, software errors, natural disasters, power outages, and network         issues.<\/p>","href":"saas\/mssql_ha_mssql_workloads.html","attributes":{"data-id":"mssql_ha_mssql_workloads"},"menu":{"hasChildren":false},"tocID":"mssql_ha_mssql_workloads-d39307e35828","topics":[]}]}};